FUNCTION INT_TO_BCD16 : WORD
VAR_INPUT
    IN : INT;
END_VAR
VAR
    v : DINT;
END_VAR
    v := INT_TO_DINT(IN);
    IF v < 0 THEN v := -v; END_IF;
    INT_TO_BCD16 := DINT_TO_WORD((v MOD 10) + ((v / 10) MOD 10) * 16 + ((v / 100) MOD 10) * 256 + ((v / 1000) MOD 10) * 4096);
END_FUNCTION

